CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY CHECK(version>0), applied_at TEXT NOT NULL, checksum TEXT NOT NULL);
CREATE TABLE model_revisions(id TEXT PRIMARY KEY, gateway_model_id TEXT NOT NULL, provider TEXT NOT NULL, model_name TEXT NOT NULL, identity_level TEXT NOT NULL, identity_hash TEXT NOT NULL UNIQUE, body_json TEXT NOT NULL CHECK(json_valid(body_json)), created_at TEXT NOT NULL);
CREATE TABLE inference_profiles(id TEXT PRIMARY KEY, profile_hash TEXT NOT NULL UNIQUE, body_json TEXT NOT NULL CHECK(json_valid(body_json)), created_at TEXT NOT NULL);
CREATE TABLE dataset_revisions(id TEXT PRIMARY KEY, benchmark_id TEXT NOT NULL, version TEXT NOT NULL, content_hash TEXT NOT NULL UNIQUE, body_json TEXT NOT NULL CHECK(json_valid(body_json)), created_at TEXT NOT NULL);
CREATE TABLE environment_snapshots(id TEXT PRIMARY KEY, snapshot_hash TEXT NOT NULL UNIQUE, body_json TEXT NOT NULL CHECK(json_valid(body_json)), captured_at TEXT NOT NULL);
CREATE TABLE artifacts(id TEXT PRIMARY KEY, sha256 TEXT NOT NULL UNIQUE CHECK(length(sha256)=64), relative_name TEXT NOT NULL CHECK(relative_name=sha256), size_bytes INTEGER NOT NULL CHECK(size_bytes>=0 AND size_bytes<=8388608), media_type TEXT NOT NULL, provenance TEXT NOT NULL CHECK(provenance IN ('offline_real','offline_fixture','simulation_replay','simulation_injected','shadow_live','canary_live')), retention_until TEXT, deleted_at TEXT, body_json TEXT NOT NULL CHECK(json_valid(body_json)));
CREATE TABLE dataset_cases(dataset_id TEXT NOT NULL REFERENCES dataset_revisions(id),case_id TEXT NOT NULL,category TEXT NOT NULL,artifact_id TEXT REFERENCES artifacts(id),fixture_artifact TEXT REFERENCES artifacts(id),case_hash TEXT NOT NULL,PRIMARY KEY(dataset_id,case_id));
CREATE TABLE evaluations(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,workflow_id TEXT NOT NULL,stable_revision_id TEXT NOT NULL REFERENCES model_revisions(id),candidate_revision_id TEXT NOT NULL REFERENCES model_revisions(id),profile_id TEXT NOT NULL REFERENCES inference_profiles(id),dataset_id TEXT NOT NULL REFERENCES dataset_revisions(id),environment_id TEXT NOT NULL REFERENCES environment_snapshots(id),source TEXT NOT NULL CHECK(source IN ('offline_real','offline_fixture')),status TEXT NOT NULL CHECK(status IN ('queued','running','completed','incomplete','cancelled','interrupted')),revision INTEGER NOT NULL CHECK(revision>0),manifest_json TEXT NOT NULL CHECK(json_valid(manifest_json)),manifest_hash TEXT NOT NULL CHECK(length(manifest_hash)=64),run_id TEXT,lease_generation INTEGER NOT NULL CHECK(lease_generation>=0),cancel_requested INTEGER NOT NULL CHECK(cancel_requested IN (0,1)),started_at TEXT NOT NULL,finished_at TEXT);
CREATE TABLE evaluation_attempts(id TEXT PRIMARY KEY,evaluation_id TEXT NOT NULL REFERENCES evaluations(id),case_id TEXT NOT NULL,arm TEXT NOT NULL CHECK(arm IN ('stable','candidate')),attempt_no INTEGER NOT NULL CHECK(attempt_no>0),lease_generation INTEGER NOT NULL CHECK(lease_generation>0),state TEXT NOT NULL CHECK(state IN ('queued','running','completed','failed','cancelled','interrupted')),verdict TEXT NOT NULL CHECK(verdict IN ('pass','functional_fail','invalid_output','compile_fail','resource_fail','infra_error','not_scored')),error_code TEXT NOT NULL,input_artifact TEXT REFERENCES artifacts(id),output_artifact TEXT REFERENCES artifacts(id),result_json TEXT NOT NULL CHECK(json_valid(result_json)),metrics_json TEXT NOT NULL CHECK(json_valid(metrics_json)),body_json TEXT NOT NULL CHECK(json_valid(body_json)),started_at TEXT NOT NULL,finished_at TEXT,UNIQUE(evaluation_id,case_id,arm,attempt_no),CHECK((state='completed' AND verdict IN ('pass','functional_fail','invalid_output','compile_fail','resource_fail')) OR (state='failed' AND verdict='infra_error') OR (state IN ('queued','running','cancelled','interrupted') AND verdict='not_scored')));
CREATE TABLE reports(id TEXT PRIMARY KEY,evaluation_id TEXT NOT NULL REFERENCES evaluations(id),report_hash TEXT NOT NULL UNIQUE,schema_version INTEGER NOT NULL CHECK(schema_version=1),body_json TEXT NOT NULL CHECK(json_valid(body_json)),created_at TEXT NOT NULL);
CREATE TABLE release_policies(id TEXT PRIMARY KEY,mode TEXT NOT NULL CHECK(mode='simulation'),policy_hash TEXT NOT NULL UNIQUE,body_json TEXT NOT NULL CHECK(json_valid(body_json)),created_at TEXT NOT NULL);
CREATE TABLE releases(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,workflow_id TEXT NOT NULL,filter_hash TEXT NOT NULL,mode TEXT NOT NULL CHECK(mode='simulation'),state TEXT NOT NULL CHECK(state IN ('DRAFT','OFFLINE_EVAL','SHADOW','CANARY_5','CANARY_25','CANARY_50','PROMOTED','PAUSED','REJECTED','ROLLED_BACK')),paused_from TEXT NOT NULL,stable_revision_id TEXT NOT NULL REFERENCES model_revisions(id),candidate_revision_id TEXT NOT NULL REFERENCES model_revisions(id),policy_id TEXT NOT NULL REFERENCES release_policies(id),report_id TEXT NOT NULL REFERENCES reports(id),revision INTEGER NOT NULL CHECK(revision>0),route_epoch INTEGER NOT NULL CHECK(route_epoch>=0),target_bps INTEGER NOT NULL CHECK(target_bps BETWEEN 0 AND 10000),admission_enabled INTEGER NOT NULL CHECK(admission_enabled IN (0,1)),body_json TEXT NOT NULL CHECK(json_valid(body_json)),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,closed_at TEXT,CHECK(stable_revision_id<>candidate_revision_id));
CREATE UNIQUE INDEX one_active_release ON releases(workspace_id,workflow_id,filter_hash,mode) WHERE closed_at IS NULL AND state NOT IN ('REJECTED','ROLLED_BACK');
CREATE TABLE release_events(id INTEGER PRIMARY KEY,release_id TEXT NOT NULL REFERENCES releases(id),sequence INTEGER NOT NULL CHECK(sequence>0),from_state TEXT NOT NULL,to_state TEXT NOT NULL,actor TEXT NOT NULL,reason_code TEXT NOT NULL,policy_hash TEXT NOT NULL,evidence_hash TEXT NOT NULL,body_json TEXT NOT NULL CHECK(json_valid(body_json)),previous_hash TEXT NOT NULL,event_hash TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(release_id,sequence));
CREATE TABLE release_assignments(release_id TEXT NOT NULL REFERENCES releases(id),session_key TEXT NOT NULL,cohort_id TEXT NOT NULL,arm TEXT NOT NULL CHECK(arm IN ('stable','candidate')),admitted_epoch INTEGER NOT NULL CHECK(admitted_epoch>=0),revoked_at TEXT,body_json TEXT NOT NULL CHECK(json_valid(body_json)),created_at TEXT NOT NULL,PRIMARY KEY(release_id,session_key));
CREATE TABLE idempotency_keys(workspace_id TEXT NOT NULL,operation TEXT NOT NULL,key TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL CHECK(json_valid(response_json)),expires_at TEXT NOT NULL,PRIMARY KEY(workspace_id,operation,key));
CREATE INDEX eval_history ON evaluations(workspace_id,started_at DESC);
CREATE INDEX case_results ON evaluation_attempts(evaluation_id,case_id,arm,attempt_no);
CREATE INDEX release_audit ON release_events(release_id,sequence);
CREATE TRIGGER evaluation_manifest_immutable BEFORE UPDATE OF manifest_json,manifest_hash,workspace_id,workflow_id,stable_revision_id,candidate_revision_id,profile_id,dataset_id,environment_id,source ON evaluations BEGIN SELECT RAISE(ABORT,'immutable evaluation manifest'); END;
CREATE TRIGGER terminal_attempt_immutable BEFORE UPDATE ON evaluation_attempts WHEN OLD.state NOT IN ('queued','running') BEGIN SELECT RAISE(ABORT,'immutable terminal attempt'); END;
CREATE TRIGGER attempts_no_delete BEFORE DELETE ON evaluation_attempts BEGIN SELECT RAISE(ABORT,'immutable attempt history'); END;
